  3	/**
  4	 * Unit tests for pure-function helpers in the config view modules.
  5	 *
  6	 * Covers:
  7	 *   - mrDeriveSlug    (config-model-registry.js)
  8	 *   - mrValidateSlug  (config-model-registry.js)
  9	 *   - mrHasChanges    (config-model-registry.js)  — reads mrModels / mrOriginal globals
 10	 *   - pmCloneAssignments (config-persona-models.js)
 11	 *
 12	 * Loading strategy: vm.runInThisContext() evaluates the vanilla JS files in the
 13	 * jsdom globalThis context so that their `var` and `function` declarations become
 14	 * accessible as globalThis properties — no module system required.
 15	 *
 16	 * Minimal stubs for dependencies referenced by non-target functions (UI,
 17	 * escapeHtml, API, configDirty) are provided in beforeAll so that loading the
 18	 * files does not throw ReferenceErrors.  The stub values are never exercised by
 19	 * the pure helpers under test.
 20	 */
 21	
 22	import { describe, it, expect, beforeAll, beforeEach } from 'vitest';
 23	import { readFileSync } from 'node:fs';
 24	import { join }         from 'node:path';
 25	import vm               from 'node:vm';
 26	
 27	// ---------------------------------------------------------------------------
 28	// Load source files via vm.runInThisContext
 29	// ---------------------------------------------------------------------------
 30	
 31	const publicDir = join(__dirname, '../../gui/public');
 32	
 33	beforeAll(() => {
 34	  // Stubs required to prevent ReferenceErrors when the broader function bodies
 35	  // in the loaded files are *parsed* (not executed — only the pure helpers are
 36	  // called, but the JS engine still needs all referenced globals to be in scope
 37	  // for `vm.runInThisContext` to succeed when `var` declarations reference them
 38	  // in other function bodies).
 39	  //
 40	  // escapeHtml and UI are loaded by setup-gui-globals.ts in jsdom environments.
 41	  // We only need to stub references that setup-gui-globals does NOT provide.
 42	
 43	  if (!(globalThis as Record<string, unknown>)['API']) {
 44	    (globalThis as Record<string, unknown>)['API'] = {};
 45	  }
 46	  if (!(globalThis as Record<string, unknown>)['configDirty']) {
 47	    (globalThis as Record<string, unknown>)['configDirty'] = {
 48	      modelRegistry:   false,
 49	      personaModels:   false,
 50	    };
 51	  }
 52	
 53	  // Load the two view modules into globalThis.
 54	  vm.runInThisContext(readFileSync(join(publicDir, 'views/config-model-registry.js'),  'utf-8'));
 55	  vm.runInThisContext(readFileSync(join(publicDir, 'views/config-persona-models.js'),  'utf-8'));
